// PMD sheets contain padded frames and built-in positional offsets. The world
// simulation owns movement, so keep the character's visual feet on its anchor.
const cache=new WeakMap();
export function spriteGeometry(image,d){let modes=cache.get(image);if(!modes){modes=new Map();cache.set(image,modes)}const key=d.w+':'+d.h;if(modes.has(key))return modes.get(key);try{const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data,cols=Math.floor(canvas.width/d.w),rows=Math.floor(canvas.height/d.h),frames=[];for(let row=0;row<rows;row++){const line=[];for(let col=0;col<cols;col++){let minX=d.w,maxX=-1,bottom=-1;for(let y=0;y<d.h;y++)for(let x=0;x<d.w;x++)if(pixels[((row*d.h+y)*canvas.width+col*d.w+x)*4+3]>32){minX=Math.min(x,minX);maxX=Math.max(x,maxX);bottom=Math.max(y,bottom)}line.push(bottom<0?null:{x:(minX+maxX+1)/2,bottom:bottom+1})}frames.push(line)}modes.set(key,frames);return frames}catch{modes.set(key,null);return null}}
